// P244: real client + paired local Noise session, fixture generated by the host scanner. Own Chromium, no :9222 tabs.
import assert from 'node:assert/strict';
import {mkdirSync,writeFileSync,readFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {startWebServer} from './serve.mjs';
import {startFakeHost} from './fakehost.mjs';
import {launch,newPage,evaluate,navigate,waitFor,waitState,shoot,sleep} from './browser.mjs';
const root=fileURLToPath(new URL('../../../',import.meta.url));const out=root+'reports/qa/p244/';mkdirSync(out,{recursive:true});
const fx=JSON.parse(readFileSync(root+'host/tests/fixtures/p244_wf.json','utf8'));
const web=await startWebServer(),fake=await startFakeHost(),B=await launch();let checks=0;const results=[];
const ev=(p,s)=>evaluate(p,s),click=(p,s)=>ev(p,s==='#orb'?`(()=>{const e=document.getElementById('orb');e.dispatchEvent(new PointerEvent('pointerdown',{button:0}));e.dispatchEvent(new PointerEvent('pointerup',{button:0}));})()`:`document.querySelector(${JSON.stringify(s)}).click()`);
const check=(v,label)=>{assert.ok(v,label);checks++;results.push(label);};
try{
 for(const scheme of ['light','dark'])for(const w of [393,1440]){
  fake.reset();fake.st.caps=['wf1'];fake.st.prefs={appearance:{language:'zh',theme:scheme},voice:{speak_replies:false,wake_enabled:false},agent:{session_mode:'shared'}};
  fake.st.onApp=async(c,m,send)=>{if(m.t==='wf_list'){if(m.etag){await send({t:'wf_same',r:m.r});return true;}for(const x of fx.wf_list)await send({...x,r:m.r});return true;}if(m.t==='wf_doc'){await send({...fx.wf_doc,r:m.r,folder:m.folder,name:m.name});return true;}if(m.t==='skill_get'){await send({...fx.skill_get,r:m.r});return true;}return false;};
  const p=await newPage(B,w,852,scheme,{allow:[web.url,fake.relay+'/'],touch:w<500});await navigate(p,fake.newPairing(web.url));await waitState(p,'awaiting-approval');await fake.approve();await waitState(p,'ready');await fake.send({t:'status',s:'idle',agent:'claude',name:'Agent J'});await ev(p,`document.getElementById('phone-env-dismiss')?.click()`);await sleep(200);
  await click(p,'#orb');await waitFor(p,`!document.getElementById('five-menu').hidden`);check(await ev(p,`document.querySelectorAll('.fp-menu-card').length===5`),'five menu cards '+scheme+w);
  writeFileSync(out+`menu-${w}-${scheme}.png`,await shoot(p,''));
  for(const page of ['workflows','skills','memory','agentj','chat']){
   if(await ev(p,`document.getElementById('five-menu').hidden`))await click(p,'#orb');await click(p,`.fp-menu-card[data-page="${page}"]`);await sleep(250);
   if(page==='workflows'){
    await waitFor(p,`document.querySelectorAll('[data-folder]').length>=3`);check(await ev(p,`!!document.querySelector('[data-folder="video-studio"]')`),'P245 example displayed '+scheme+w);
   }
   writeFileSync(out+`${page}-${w}-${scheme}.png`,await shoot(p,''));
  }
  await fake.send({t:'busy',by:'Agent J',tasks:[
   {id:'writer',who:'编剧',kind:'temp',label:'写下一集',harness:'codex',model:'gpt-6.1-sol',workflow:'video-studio',company:'影片公司',role:'编剧',parent:'导演阿影',c:1,since:Math.floor(Date.now()/1000)},
   {id:'helper',who:null,kind:'temp',label:'校对',harness:'opencode',model:'deepseek/deepseek-chat',c:2,since:Math.floor(Date.now()/1000)}]});
  await waitFor(p,`!document.getElementById('busyDots').hidden`);await click(p,'#busyDots');
  check(await ev(p,`document.getElementById('busyTasksTab').getAttribute('aria-selected')==='true'`),'working default tab '+scheme+w);
  check(await ev(p,`document.getElementById('busyList').textContent.includes('gpt-6.1-sol') && document.getElementById('busyList').textContent.includes('OpenAI')`),'harness and model '+scheme+w);
  check(await ev(p,`!!document.querySelector('.busy-vendor img[src$="opencode-dark.svg"]')`),'official mark matches dark working card '+scheme+w);
  await waitFor(p,`document.querySelectorAll('.busy-vendor[data-palette]').length===2`);
  check(await ev(p,`[...document.querySelectorAll('.busy-vendor[data-palette]')].every(e=>e.dataset.palette==='ready')`),'vendor palette ready: '+JSON.stringify(await ev(p,`[...document.querySelectorAll('.busy-vendor[data-palette]')].map(e=>e.dataset.paletteError||e.dataset.palette)`)));
  check(await ev(p,`(()=>{const approved=new Set(['rgb(250, 249, 245)','rgb(44, 43, 38)','rgb(133, 133, 133)']);return [...document.querySelectorAll('.busy-palette-mark path,.busy-palette-mark rect')].every(e=>approved.has(getComputedStyle(e).fill));})()`),'licensed mark renders approved palette only '+scheme+w);
  writeFileSync(out+`robots-working-${w}-${scheme}.png`,await shoot(p,''));
  await click(p,'#busyWorkflowTab');
  check(await ev(p,`!document.getElementById('busyWorkflow').hidden && document.getElementById('busyWorkflow').textContent.includes('第 4 层') && document.getElementById('busyWorkflow').textContent.includes('不属于任何工作流')`),'workflow hierarchy and temporary helper '+scheme+w);
  writeFileSync(out+`robots-workflow-${w}-${scheme}.png`,await shoot(p,''));await click(p,'#busyClose');
  await click(p,'#orb');await click(p,'.fp-menu-card[data-page="workflows"]');await click(p,'[data-folder="video-studio"] .fp-at');
  check(await ev(p,`document.getElementById('input').value.includes('@video-studio（CEO 导演阿影）')`),'mention plain text '+scheme+w);
  check(await ev(p,`document.getElementById('five-page').hidden`),'mention goes to chat '+scheme+w);
  check(await ev(p,`document.querySelector('#workflow-compose .workflow-token')?.contentEditable==='false'`),'atomic mention token '+scheme+w);
  writeFileSync(out+`mention-${w}-${scheme}.png`,await shoot(p,''));
  await ev(p,`(()=>{const bytes=Uint8Array.from(atob('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVQIHWP4z8DwHwAFgAI/ScLbtAAAAABJRU5ErkJggg=='),c=>c.charCodeAt(0));const dt=new DataTransfer();dt.items.add(new File([bytes],'p244-paste.png',{type:'image/png'}));document.getElementById('workflow-compose').dispatchEvent(new ClipboardEvent('paste',{clipboardData:dt,bubbles:true,cancelable:true}));})()`);
  await waitFor(p,`document.getElementById('tray').children.length>0`);
  check(await ev(p,`!!document.querySelector('.workflow-token') && document.getElementById('input').value.includes('CEO')`),'paste image with workflow token '+scheme+w);
  check(await ev(p,`(()=>{const editor=document.getElementById('workflow-compose'),sel=getSelection(),r=document.createRange();r.selectNodeContents(editor);sel.removeAllRanges();sel.addRange(r);const dt=new DataTransfer();editor.dispatchEvent(new ClipboardEvent('copy',{clipboardData:dt,bubbles:true,cancelable:true}));return dt.getData('text/plain').includes('@video-studio（CEO 导演阿影）')&&!dt.getData('text/plain').includes('<span');})()`),'clipboard plain mention '+scheme+w);
  await ev(p,`(()=>{const e=document.getElementById('workflow-compose'),r=document.createRange();r.selectNodeContents(e);r.collapse(false);const s=getSelection();s.removeAllRanges();s.addRange(r);e.focus();})()`);
  await p.send('Input.dispatchKeyEvent',{type:'keyDown',key:'k',code:'KeyK',ctrlKey:true});
  check(await ev(p,`!document.body.dataset.search`),'capsule Ctrl+K stays in composer '+scheme+w);
  await ev(p,`(()=>{const e=document.getElementById('workflow-compose'),r=document.createRange();r.selectNode(e.querySelector('.workflow-token'));const s=getSelection();s.removeAllRanges();s.addRange(r);e.focus();})()`);
  await p.send('Input.dispatchKeyEvent',{type:'keyDown',key:'Backspace',code:'Backspace',windowsVirtualKeyCode:8});
  await waitFor(p,`!document.querySelector('#workflow-compose .workflow-token')`);
  check(await ev(p,`!document.getElementById('input').value.includes('CEO')`),'delete whole mention '+scheme+w);
  await ev(p,`(()=>{const i=document.getElementById('input');i.value='老板@';i.setSelectionRange(i.value.length,i.value.length);i.dispatchEvent(new Event('input'));})()`);
  check(await ev(p,`!document.getElementById('five-mentions').hidden`),'Han trigger '+scheme+w);
  await click(p,'.fp-mention');check(await ev(p,`document.getElementById('input').value.startsWith('老板@')`),'caret replacement '+scheme+w);
  await ev(p,`(()=>{const i=document.getElementById('input');i.value='a@example.com';i.setSelectionRange(i.value.length,i.value.length);i.dispatchEvent(new Event('input'));})()`);
  check(await ev(p,`document.getElementById('five-mentions').hidden`),'email negative '+scheme+w);
  await click(p,'#orb');await click(p,'.fp-menu-card[data-page="agentj"]');await click(p,'#five-body .fp-card-head');await waitFor(p,`!document.getElementById('five-detail').hidden && document.querySelector('.fp-prose').textContent.includes('导演')`);
  check(await ev(p,`[...document.querySelectorAll('#five-detail button')].every(b=>!b.textContent.includes('讨论'))`),'core has no discuss '+scheme+w);
  await p.send('Input.dispatchKeyEvent',{type:'keyDown',key:'Escape',code:'Escape',windowsVirtualKeyCode:27});check(await ev(p,`document.getElementById('five-detail').hidden`),'Esc closes top layer '+scheme+w);
  check(await ev(p,`!document.body.dataset.uiError`),'no UI error '+scheme+w);
  await p.dispose();
 }
 const rules=await newPage(B,393,852,'dark',{allow:[web.url]});await navigate(rules,web.url);
 const vectors=[['@',true],['老板@',true],['，@video',true],['（@',true],['\n@',true],['　@',true],['a@',false],['a@example.com',false],['a.b@',false],['x+@',false],['1@',false],['@foo bar',false]];
 for(const [value,expected] of vectors){check(await ev(rules,`import('./js/five-pages.js').then(m=>!!m.mentionAt(${JSON.stringify(value)}))`)===expected,'mention boundary '+JSON.stringify(value));}
 await rules.dispose();
 console.log(`P244 PASS ${checks} checks`);writeFileSync(out+'browser.json',JSON.stringify({ok:true,checks,results},null,2));
}finally{await B.close();await fake.stop();await web.stop();}
